package com.dating.backend.matching;
import com.dating.backend.entity.*;import jakarta.persistence.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class AdminConsoleService {
 private final EntityManager em;
 public record Member(Long id,String email,String nickname,String status,boolean resting,String reviewStatus,long revision,String reviewNote,String risk,int riskScore,LocalDateTime createdAt,int warningCount,String sanctionType,Instant suspendedUntil,long totalBlockCount,long activeBlockCount){}
 public record Page(List<Member> items,long total,int page){}
 public record Detail(Member member,UserProfile profile,UserVerification verification,List<UserProfileImage> images,ApprovedProfile approved,List<AdminReviewHistory> history,List<TermsConsent> consents){}
 private Member member(User u){return new Member(u.getId(),u.getEmail(),u.getNickname(),u.getStatus(),u.isResting(),u.getProfileReviewStatus(),u.getProfileRevision(),u.getProfileReviewNote(),u.getFraudReviewStatus(),u.getFraudRiskScore(),u.getCreatedAt(),u.getWarningCount(),u.getSanctionType(),u.getSuspendedUntil(),Math.max(u.getTotalBlockCount(),blockCount(u.getId())),blockCount(u.getId()));}
 private long blockCount(Long id){return em.createQuery("select count(v) from MemberVisibility v where v.targetId=:id and v.blocked=true",Long.class).setParameter("id",id).getSingleResult();}
 @Transactional(readOnly=true) public Page members(String q,String status,String review,int page,String sort){
  if(page<0||page>10000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);String order=switch(sort){case "OLDEST"->"u.createdAt asc,u.id asc";case "WARNINGS"->"u.warningCount desc,u.id desc";case "BLOCKS"->"greatest(u.totalBlockCount,(select count(v) from MemberVisibility v where v.targetId=u.id and v.blocked=true)) desc,u.id desc";case "SUSPENSION_END"->"u.suspendedUntil asc,u.id desc";default->"u.createdAt desc,u.id desc";};String filter=" where (:status='ALL' or u.status=:status) and (:review='ALL' or u.profileReviewStatus=:review) and (lower(u.nickname) like :q or lower(u.email) like :q)";
  String query="%"+(q==null?"":q.toLowerCase(Locale.ROOT).replace("%","").replace("_",""))+"%";
  var rows=em.createQuery("select u from User u"+filter+" order by "+order,User.class).setParameter("status",status).setParameter("review",review).setParameter("q",query).setFirstResult(page*30).setMaxResults(30).getResultList();
  long count=em.createQuery("select count(u) from User u"+filter,Long.class).setParameter("status",status).setParameter("review",review).setParameter("q",query).getSingleResult();return new Page(rows.stream().map(this::member).toList(),count,page);
 }
 @Transactional(readOnly=true) public Detail detail(Long id){var u=em.find(User.class,id);if(u==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return new Detail(member(u),em.createQuery("select p from UserProfile p where p.userId=:u",UserProfile.class).setParameter("u",id).getResultStream().findFirst().orElse(null),em.createQuery("select v from UserVerification v where v.userId=:u",UserVerification.class).setParameter("u",id).getResultStream().findFirst().orElse(null),em.createQuery("select i from UserProfileImage i where i.userId=:u order by i.isMain desc,i.imageOrder",UserProfileImage.class).setParameter("u",id).getResultList(),em.find(ApprovedProfile.class,id),em.createQuery("select h from AdminReviewHistory h where h.userId=:u order by h.id desc",AdminReviewHistory.class).setParameter("u",id).setMaxResults(30).getResultList(),em.createQuery("select t from TermsConsent t where t.userId=:u order by t.id desc",TermsConsent.class).setParameter("u",id).getResultList());}
 @Transactional(readOnly=true) public Map<String,Long> summary(){return Map.of("members",count("User",""),"signup",count("User"," where e.status='PENDING_REVIEW'"),"changes",count("User"," where e.profileReviewStatus='PENDING' and e.status='ACTIVE'"),"inquiries",count("SupportInquiry"," where e.status in ('OPEN','IN_PROGRESS')"),"reports",count("UserReport"," where e.status='OPEN'"),"withdrawn",count("User"," where e.status='DELETED'"));}
 private long count(String entity,String filter){return em.createQuery("select count(e) from "+entity+" e"+filter,Long.class).getSingleResult();}
}
